'use client'

import { useMemo, useState } from 'react'
import { BarChart3, Bell, BookOpen, BookOpenCheck, ChevronDown, FileText, Languages, LayoutDashboard, Library, Menu, Mic, MoreHorizontal, Plus, Search, Settings, Sparkles, Trophy, Users } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Progress } from '@/components/ui/progress'

type Role = 'teacher' | 'student'
type Section = 'Dashboard' | 'Students' | 'Lessons' | 'Translator' | 'Voice Translator' | 'Quizzes' | 'Progress' | 'Library' | 'Reports' | 'Settings'

type Lesson = { title: string; subtitle: string; language: string; color: string; icon: string; className: string }

const navigation: { label: Section; icon: typeof LayoutDashboard }[] = [
  { label: 'Dashboard', icon: LayoutDashboard }, { label: 'Students', icon: Users }, { label: 'Lessons', icon: FileText }, { label: 'Translator', icon: Languages }, { label: 'Voice Translator', icon: Mic }, { label: 'Quizzes', icon: BookOpenCheck }, { label: 'Progress', icon: BarChart3 }, { label: 'Library', icon: Library }, { label: 'Reports', icon: Trophy }, { label: 'Settings', icon: Settings },
]

const lessons: Lesson[] = [
  { title: 'Parts of Plants', subtitle: 'Science · Class 3', language: 'हिंदी', color: 'bg-[#eee9ff]', icon: '🌱', className: 'Class 3' },
  { title: 'Identify Colors', subtitle: 'English · Class 3', language: 'संथाली', color: 'bg-[#e7f1ff]', icon: '🎨', className: 'Class 3' },
  { title: 'The Water Cycle', subtitle: 'Science · Class 6', language: 'हो', color: 'bg-[#e8f6ed]', icon: '💧', className: 'Class 6' },
  { title: 'Our Forest Friends', subtitle: 'EVS · Class 5', language: 'मुंडारी', color: 'bg-[#fff0dc]', icon: '🌿', className: 'Class 5' },
]

const students = [{ name: 'Anjali Kumari', className: 'Class 3', score: 92, color: 'bg-[#f6cfc1]' }, { name: 'Rohit Hansda', className: 'Class 3', score: 89, color: 'bg-[#cadcf6]' }, { name: 'Meera Tudu', className: 'Class 3', score: 85, color: 'bg-[#f4dfaa]' }, { name: 'Arjun Mahato', className: 'Class 3', score: 82, color: 'bg-[#d7e6c6]' }, { name: 'Pooja Kumari', className: 'Class 3', score: 80, color: 'bg-[#e5d2e9]' }]

function Initials({ name, className }: { name: string; className: string }) { return <div className={`grid h-8 w-8 place-items-center rounded-full text-[10px] font-bold text-[#263250] ${className}`}>{name.split(' ').map(word => word[0]).join('').slice(0, 2)}</div> }

function Sidebar({ active, setActive, role }: { active: Section; setActive: (item: Section) => void; role: Role }) { return <aside className="reference-sidebar hidden lg:flex"><div className="reference-brand"><div className="reference-leaf">◆</div><div><strong>Vernacular<br />Learning</strong><span>AI Powered Education</span></div></div><nav className="reference-nav">{navigation.map(({ label, icon: Icon }) => <button key={label} onClick={() => setActive(label)} className={active === label ? 'active' : ''}><Icon size={17} />{label}{label === 'Voice Translator' && <span className="nav-dot" />}</button>)}</nav><div className="reference-profile"><Initials name={role === 'teacher' ? 'Sunita Kumari' : 'Aman Raj'} className="bg-[#f2c4b8]" /><div><strong>{role === 'teacher' ? 'Sunita Kumari' : 'Aman Raj'}</strong><span>{role === 'teacher' ? 'Teacher' : 'Student'}</span></div><ChevronDown size={14} /></div></aside> }

function Metric({ icon: Icon, value, label, note, color }: { icon: typeof Users; value: string; label: string; note: string; color: string }) { return <Card className="reference-metric"><CardContent><div className={`metric-icon ${color}`}><Icon size={20} /></div><div><strong>{value}</strong><span>{label}</span><small><b>↑</b> {note}</small></div></CardContent></Card> }

function PerformanceChart() { return <Card className="reference-panel performance"><CardHeader><CardTitle>Student Performance Overview</CardTitle><select aria-label="Performance period" defaultValue="month"><option value="month">This Month</option><option value="term">This Term</option></select></CardHeader><CardContent><div className="chart-y"><span>100</span><span>75</span><span>50</span><span>25</span><span>0</span></div><div className="chart-area"><div className="chart-grid" /><svg viewBox="0 0 500 180" preserveAspectRatio="none" role="img" aria-label="Student performance trend"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#6458e8" stopOpacity=".22" /><stop offset="1" stopColor="#6458e8" stopOpacity="0" /></linearGradient></defs><path d="M0 122 C28 90, 42 98, 65 111 S98 137, 120 88 S152 103, 180 120 S210 145, 235 81 S270 107, 295 68 S330 84, 352 92 S385 122, 408 73 S442 94, 470 62 S490 72, 500 52 L500 180 L0 180 Z" fill="url(#chartFill)" /><path d="M0 122 C28 90, 42 98, 65 111 S98 137, 120 88 S152 103, 180 120 S210 145, 235 81 S270 107, 295 68 S330 84, 352 92 S385 122, 408 73 S442 94, 470 62 S490 72, 500 52" fill="none" stroke="#5b54d8" strokeWidth="3" /></svg><div className="chart-point" /><div className="chart-tooltip"><b>14 May</b><strong>82%</strong></div><div className="chart-x"><span>1 May</span><span>7 May</span><span>14 May</span><span>21 May</span><span>28 May</span></div></div></CardContent></Card> }

function LessonsDonut() { return <Card className="reference-panel completed"><CardHeader><CardTitle>Lessons Completed</CardTitle></CardHeader><CardContent><div className="donut-wrap"><div className="donut"><strong>25</strong><span>Total</span></div></div><div className="legend">{[['Science', '8 (32%)', '#6a4de6'], ['Maths', '6 (24%)', '#5688e7'], ['Language', '5 (20%)', '#54b875'], ['EVS', '4 (16%)', '#f1a433'], ['Others', '2 (8%)', '#f4cf4e']].map(([label, value, color]) => <span key={label}><i style={{ background: color }} />{label}<b>{value}</b></span>)}</div></CardContent></Card> }

function Activity() { const items = [['New lesson added', 'पौधों के भाग (Parts of Plants)', '2 hours ago', 'bg-[#def3e5]'], ['Quiz completed', 'रंगों की पहचान (Identify Colors)', '5 hours ago', 'bg-[#e4efff]'], ['Student joined', 'Rahul Kumar joined class 3', '1 day ago', 'bg-[#ece8ff]'], ['Voice translation used', '“Good Morning” → “सुप्रभात”', '1 day ago', 'bg-[#f0e4ff]'], ['Quiz attempted', 'Animals Quiz by 15 students', '2 days ago', 'bg-[#fff0dd]']]; return <Card className="reference-panel activity"><CardHeader><CardTitle>Recent Activity</CardTitle></CardHeader><CardContent>{items.map(([title, detail, time, color], index) => <div className="activity-row" key={title}><div className={`activity-icon ${color}`}><span>{['▣', '▤', '♟', '♬', '✓'][index]}</span></div><div><strong>{title}</strong><span>{detail}</span></div><time>{time}</time></div>)}<Button variant="outline" size="sm">View All</Button></CardContent></Card> }

function QuickActions({ announce }: { announce: (message: string) => void }) { const actions = [{ label: 'Create Lesson', detail: 'Add new lesson', icon: FileText, color: 'bg-[#eee8ff]' }, { label: 'Create Quiz', detail: 'Add new quiz', icon: BookOpenCheck, color: 'bg-[#e4f0ff]' }, { label: 'Use Translator', detail: 'Translate text', icon: Languages, color: 'bg-[#e3f5e8]' }, { label: 'Voice Translator', detail: 'Speak & translate', icon: Mic, color: 'bg-[#ffeadc]' }, { label: 'View Reports', detail: 'Check reports', icon: BarChart3, color: 'bg-[#fff2d8]' }]; return <div className="quick-actions">{actions.map(({ label, detail, icon: Icon, color }) => <button key={label} onClick={() => announce(`${label} opened`)} className={color}><Icon size={21} /><strong>{label}</strong><span>{detail}</span></button>)}</div> }

function DashboardContent({ active, role, announce, query, setQuery }: { active: Section; role: Role; announce: (message: string) => void; query: string; setQuery: (value: string) => void }) { const filtered = useMemo(() => lessons.filter(lesson => `${lesson.title} ${lesson.subtitle}`.toLowerCase().includes(query.toLowerCase())), [query]); if (active === 'Dashboard') return <><div className="reference-welcome"><div><span>WELCOME BACK, {role === 'teacher' ? 'SUNITA KUMARI' : 'AMAN RAJ'}! 👋</span><h1>Empowering children through their mother tongue.</h1></div><div className="welcome-illustration">👩🏾‍🏫<span>👦🏽 👧🏽 👦🏽</span></div><div className="teaching-language"><div>अ</div><span>Your Teaching Language<strong>हिंदी (Hindi)</strong></span></div></div><div className="reference-metrics"><Metric icon={Users} value={role === 'teacher' ? '120' : '7'} label={role === 'teacher' ? 'Total Students' : 'Lessons Completed'} note={role === 'teacher' ? '12% this month' : '3 this week'} color="purple" /><Metric icon={BookOpen} value="25" label="Total Lessons" note="5 this week" color="blue" /><Metric icon={BookOpenCheck} value="18" label="Total Quizzes" note="3 this week" color="green" /><Metric icon={BarChart3} value="78%" label="Avg. Performance" note="8% this month" color="orange" /></div><div className="reference-grid"><PerformanceChart /><LessonsDonut /><Activity /></div><div className="reference-lower"><Card className="reference-panel actions-panel"><CardHeader><CardTitle>Quick Actions</CardTitle></CardHeader><CardContent><QuickActions announce={announce} /></CardContent></Card><Card className="reference-panel top-students"><CardHeader><CardTitle>Top Students</CardTitle><button onClick={() => announce('Student list opened')}>View All</button></CardHeader><CardContent>{students.map((student, index) => <div className="student-row" key={student.name}><span className="rank">{index + 1}</span><Initials name={student.name} className={student.color} /><strong>{student.name}</strong><span>{student.className}</span><b>{student.score}%</b></div>)}</CardContent></Card></div><Card className="reference-panel languages-panel"><CardHeader><CardTitle>Recently Used Languages</CardTitle></CardHeader><CardContent>{['हिंदी|Hindi', 'English|English', 'संथाली|Santhali', 'हो|Ho', 'मुंडारी|Mundari'].map(item => { const [native, english] = item.split('|'); return <button key={item} onClick={() => announce(`${english} selected`)}><strong>{native}</strong><span>{english}</span></button> })}<button className="add-language" onClick={() => announce('Language picker opened')}><Plus size={14} />Add Language</button></CardContent></Card></>; return <div className="section-placeholder"><div className="placeholder-icon"><Languages size={28} /></div><h1>{active}</h1><p>{active === 'Lessons' ? 'Browse and manage the lessons shared with your classes.' : 'This workspace is ready for your classroom workflow.'}</p><div className="reference-search"><Search size={16} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder={`Search ${active.toLowerCase()}`} /></div><div className="placeholder-list">{filtered.map(lesson => <button key={lesson.title} onClick={() => announce(`${lesson.title} opened`)}><span className={`lesson-symbol ${lesson.color}`}>{lesson.icon}</span><span><strong>{lesson.title}</strong><small>{lesson.subtitle} · {lesson.language}</small></span><ChevronDown size={16} /></button>)}</div></div> }

export default function ReferenceDashboard({ role, onLogout }: { role: Role; onLogout: () => void }) { const [active, setActive] = useState<Section>('Dashboard'); const [query, setQuery] = useState(''); const [notice, setNotice] = useState(''); const [notifications, setNotifications] = useState(false); const announce = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 2800) }; return <div className="reference-app"><Sidebar active={active} setActive={setActive} role={role} /><div className="reference-main"><header className="reference-header"><button className="mobile-menu" onClick={() => announce('Use the sidebar on a wider screen')}><Menu size={20} /></button><div className="header-title"><span>☰</span><strong>{active}</strong></div><div className="header-tools"><button className="header-language">हिंदी <ChevronDown size={13} /></button><button aria-label="Notifications" onClick={() => setNotifications(!notifications)} className="notification-button"><Bell size={19} /><b>3</b></button><Initials name={role === 'teacher' ? 'Sunita Kumari' : 'Aman Raj'} className="bg-[#f2c4b8]" /><ChevronDown size={14} /></div>{notifications && <div className="notification-popover"><strong>Notifications</strong><span>Class 6 is ready for today’s lesson.</span><span>New translated lesson shared.</span></div>}</header><main className="reference-content"><DashboardContent active={active} role={role} announce={announce} query={query} setQuery={setQuery} /></main><footer className="reference-footer">© 2026 Vernacular Learning <span>Accessible education in every mother tongue.</span><button onClick={onLogout}>Sign out</button></footer></div>{notice && <div className="reference-toast"><Sparkles size={15} />{notice}</div>}</div> }
